import allocationDocument from "../../../materials/allocation.json";
import type { Condition, Stratum } from "@eiai/schema";

/**
 * Condition assignment from the committed, seeded sequence
 * (`materials/allocation.json`, generated by `pipeline/allocation.py`).
 *
 * This replaces a hard-coded `warm` / `en:adult` literal that had two
 * consequences worth naming, because both were invisible from inside the app:
 *
 *  1. The neutral arm was unreachable. Half the design could not be walked
 *     end to end, so no browser test could ever have exercised it.
 *  2. The stratum was recorded as `en:adult` regardless of the language and
 *     age the participant actually chose on the eligibility screen, so the
 *     event log would have contradicted the participant's own answers for
 *     everyone who was not an English-speaking adult.
 *
 * Index derivation
 * ----------------
 * The index comes from the session id, so assignment is deterministic and
 * needs no backend: given the log, anyone can recompute which sequence entry a
 * session should have drawn. The cost is that two participants can land on the
 * same index, so the block balance the sequence guarantees holds only in
 * expectation. Handing out indices from the ingest service makes it exact, and
 * `allocation_seq` is recorded either way, so realised balance is always
 * checkable from the log rather than assumed.
 */

type AllocationDocument = {
  readonly seed: number;
  readonly block_size: number;
  readonly sequence: Record<string, readonly string[]>;
  readonly sequence_sha256: string;
};

const document = allocationDocument as AllocationDocument;

export class AllocationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "AllocationError";
  }
}

/**
 * FNV-1a, 32-bit. Chosen because it is four lines and its behaviour is
 * identical in every language a re-analysis might be written in -- an audit
 * that cannot reproduce the index cannot check the allocation.
 */
export function hashToIndex(sessionId: string, length: number): number {
  if (length <= 0) throw new AllocationError("allocation sequence is empty");
  let hash = 0x811c9dc5;
  for (let i = 0; i < sessionId.length; i += 1) {
    hash ^= sessionId.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash % length;
}

export type Allocation = {
  readonly condition: Condition;
  readonly stratum: Stratum;
  readonly allocationSeq: number;
};

/**
 * Slot indices already spoken for, supplied by the caller.
 *
 * Empty in the offline build: without the ingest service there is nothing that
 * knows what other sessions have taken, so the session-id hash stands in and
 * two simultaneous participants can collide. `pipeline/slots.py` computes the
 * real set from the event log, and the ingest service will serve it. Passing it
 * in rather than reaching for it keeps this module free of transport concerns
 * and makes exhaustion testable.
 */
export type TakenSlots = ReadonlySet<number>;

export class SlotsExhaustedError extends Error {
  constructor(readonly stratum: Stratum) {
    super(
      `every slot in stratum '${stratum}' is taken. Recruitment into this ` +
        `stratum is closed; the sequence must not wrap, because two participants ` +
        `at the same index would break the block balance with nothing in the log ` +
        `to show it.`,
    );
    this.name = "SlotsExhaustedError";
  }
}

export function allocate(
  sessionId: string,
  stratum: Stratum,
  taken: TakenSlots = new Set(),
): Allocation {
  const sequence = document.sequence[stratum];
  if (!sequence) {
    // Throwing rather than falling back to a default arm: a silent default
    // would put a fabricated condition in the permanent log, and nothing
    // downstream could tell it apart from a real assignment.
    throw new AllocationError(
      `no allocation sequence for stratum '${stratum}'. Regenerate with pipeline/allocation.py.`,
    );
  }
  // Start from the hashed position and walk forward to the first free slot.
  // Walking rather than wrapping blindly is what turns exhaustion into a
  // reportable state instead of a silent double-booking.
  const start = hashToIndex(sessionId, sequence.length);
  let index = -1;
  for (let offset = 0; offset < sequence.length; offset += 1) {
    const candidate = (start + offset) % sequence.length;
    if (!taken.has(candidate)) {
      index = candidate;
      break;
    }
  }
  if (index === -1) throw new SlotsExhaustedError(stratum);

  const condition = sequence[index];
  if (condition !== "warm" && condition !== "neutral") {
    throw new AllocationError(`allocation sequence holds an unknown condition '${condition}'`);
  }
  return { condition, stratum, allocationSeq: index };
}

export const allocationSeed = document.seed;
export const allocationSha256 = document.sequence_sha256;
